"""Additive, resumable Feishu workbench deployment. No legacy record overwrites."""
import json, pathlib
from snapshot import cli, ROOT, BASE
STATE=ROOT/'deployment.json'
state=json.loads(STATE.read_text()) if STATE.exists() else {'tables':{},'rows':{},'formulas':{}}
def save(): STATE.write_text(json.dumps(state,ensure_ascii=False,indent=2))
def t(name): return {'name':name,'type':'text'}
def n(name): return {'name':name,'type':'number','style':{'type':'plain','precision':4}}
def link(name,table): return {'name':name,'type':'link','link_table':state['tables'][table]}
def table(name,fields):
    if name not in state['tables']:
        existing={x['name']:x['id'] for x in cli('+table-list')['tables']}
        if name in existing: state['tables'][name]=existing[name]
        else:
            x=cli('+table-create','--name',name,'--fields',json.dumps(fields,ensure_ascii=False))
            ids=cli('+table-list')['tables']; state['tables'][name]=next(x['id'] for x in ids if x['name']==name)
        save()
    fs=cli('+field-list','--table-id',state['tables'][name])['fields']
    (ROOT/(name+'.schema.json')).write_text(json.dumps(fs,ensure_ascii=False,indent=2))
    print('TABLE',name,flush=True)
def rows(name,records):
    if name in state['rows']: return state['rows'][name]
    x=cli('+record-batch-create','--table-id',state['tables'][name],'--json',json.dumps({'create_records':records},ensure_ascii=False))
    ids=x.get('record_id_list')
    if ids is None:
        print(x);raise RuntimeError('Unexpected record response')
    state['rows'][name]=ids;save();print('ROWS',name,len(ids),flush=True);return ids
def formulas(name,definitions):
    fs=cli('+field-list','--table-id',state['tables'][name])['fields']; existing={x['name'] for x in fs}
    pending=[{'name':k,'type':'formula','expression':v} for k,v in definitions.items() if k not in existing]
    if pending:
        cli('+field-create','--table-id',state['tables'][name],'--json',json.dumps(pending,ensure_ascii=False),'--i-have-read-guide')
    state['formulas'][name]=definitions;save();print('FORMULAS',name,len(definitions),flush=True)
def refs(ids):return [{'id':x} for x in ids]
